// js/utils.js — helpers puros (sem dependências)
// Todos exportados individualmente para TDD

const clamp = (v, min, max) => {
  return Math.max(min, Math.min(max, v));
};

const lerp = (a, b, t) => {
  return a + (b - a) * t;
};

const deg2rad = (d) => {
  return (d * Math.PI) / 180;
};

// WHY: rotação positiva mantém movimento alinhado à câmera
// R_y(+yaw) = {x: sin(yaw), z: cos(yaw)} — ciclo correto para FPS
const R_y = (yaw) => {
  const sy = Math.sin(yaw);
  const cy = Math.cos(yaw);
  return { x: sy, z: cy };
};

const angleLerp = (a, b, t) => {
  // Shortest-path lerp entre ângulos (evita descontinuidade em ±π)
  let diff = b - a;
  if (diff > Math.PI) diff -= 2 * Math.PI;
  if (diff < -Math.PI) diff += 2 * Math.PI;
  return a + diff * clamp(t, 0, 1);
};

const dist2D = (ax, az, bx, bz) => {
  const dx = bx - ax;
  const dz = bz - az;
  return Math.sqrt(dx * dx + dz * dz);
};

// mulberry32 — PRNG determinístico com seed
const mulberry32 = (seed) => {
  let s = seed >>> 0;
  return function () {
    s = (s + 0x6D2B79F5) >>> 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) >>> 0;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
};

export { clamp, lerp, deg2rad, R_y, angleLerp, dist2D, mulberry32 };

