// js/engine.js — Three.js scene setup (renderer, camera, fog, lights)
import * as THREE from '../vendor/three.module.js';
import C from './constants.js';

const createEngine = (canvas) => {
  const renderer = new THREE.WebGLRenderer({
    canvas,
    antialias: false,
  });
  renderer.setPixelRatio(Math.min(devicePixelRatio, 1.5));
  renderer.autoClear = true;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(C.RENDER.background);
  scene.fog = new THREE.Fog(
    C.RENDER.background,
    C.RENDER.fogNear,
    C.RENDER.fogFar
  );

  const camera = new THREE.PerspectiveCamera(
    75,
    canvas.clientWidth / canvas.clientHeight,
    0.1,
    120
  );
  camera.position.set(0, C.PLAYER.height, 0);

  const hemi = new THREE.HemisphereLight(
    C.LIGHT.hemiSky,
    C.LIGHT.hemiGround,
    C.LIGHT.hemiIntensity
  );
  hemi.position.set(0, 50, 0);

  const ambient = new THREE.AmbientLight(C.LIGHT.ambient, 1.0);

  const world = new THREE.Group();
  scene.add(hemi);
  scene.add(ambient);
  scene.add(world);

  const resize = () => {
    const w = canvas.clientWidth;
    const h = canvas.clientHeight;
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
    renderer.setSize(w, h);
  };

  // Loop helper com fixed-step e interpolação alpha
  const STEP = C.PHYSICS.step;
  const createLoop = (updateFn, renderFn) => {
    let accumulator = 0;
    let lastTime = performance.now();
    const loop = (now) => {
      const rawDt = (now - lastTime) / 1000;
      lastTime = now;
      const dt = Math.min(rawDt, 0.016);
      accumulator += dt;
      while (accumulator >= STEP) {
        updateFn(STEP);
        accumulator -= STEP;
      }
      if (renderFn) renderFn(accumulator / STEP);
      window.__debugStats = window.__debugStats || { calls: 0 };
      window.__debugStats.calls++;
      requestAnimationFrame(loop);
    };
    requestAnimationFrame(loop);
    return { resize, render };
  };

  window.addEventListener('resize', resize);

  return { renderer, scene, camera, world, lights: { hemi, ambient, torches: [] }, resize, createLoop };
};

export { createEngine };

