// js/input.js — gerenciador de teclado/mouse para FPS
const KEYS = [
  'KeyW', 'KeyA', 'KeyS', 'KeyD',
  'ShiftLeft', 'Space',
  'KeyP', 'KeyM',
  'Digit1', 'Digit2', 'Digit3', 'Digit4',
  'KeyE',
  'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight',
];

class Input {
  constructor(canvas) {
    this._keys = {};
    this._justPressed = new Set();
    this._locked = false;
    this._yaw = 0;
    this._pitch = 0;
    this._sensitivity = 0.002;
    this._lastMouseX = 0;
    this._lastMouseY = 0;

    this._initKeyboard();
    this._initPointer();
  }

  _initKeyboard() {
    document.addEventListener('keydown', (e) => {
      if (KEYS.includes(e.code)) {
        this._keys[e.code] = true;
        this._justPressed.add(e.code);
      }
      e.preventDefault();
    });
    document.addEventListener('keyup', (e) => {
      if (KEYS.includes(e.code)) {
        this._keys[e.code] = false;
      }
    });
  }

  _initPointer() {
    const canvasEl = document.querySelector('canvas');
    canvasEl.addEventListener('click', () => {
      if (!this._locked) {
        canvasEl.requestPointerLock();
      }
    });

    document.addEventListener('pointerlockchange', () => {
      this._locked = document.pointerLockElement === canvasEl;
    });

    document.addEventListener('mousemove', (e) => {
      if (!this._locked) return;
      this._yaw -= e.movementX * this._sensitivity;
      this._pitch -= e.movementY * this._sensitivity;
      this._pitch = Math.max(-Math.PI / 2, Math.min(Math.PI / 2, this._pitch));
      // WHY: rotação positiva mantém movimento alinhado à câmera
      this._yaw = (this._yaw + Math.PI) % (2 * Math.PI) - Math.PI;
    });
  }

  isDown(code) {
    return this._keys[code] === true;
  }

  consume(code) {
    this._justPressed.delete(code);
  }

  getAxis() {
    let x = 0, z = 0;
    if (this.isDown('KeyW')) z -= 1;
    if (this.isDown('KeyS')) z += 1;
    if (this.isDown('KeyA')) x -= 1;
    if (this.isDown('KeyD')) x += 1;
    if (this.isDown('ArrowUp')) z -= 1;
    if (this.isDown('ArrowDown')) z += 1;
    if (this.isDown('ArrowLeft')) x -= 1;
    if (this.isDown('ArrowRight')) x += 1;
    const len = Math.sqrt(x * x + z * z);
    if (len > 0) { x /= len; z /= len; }
    return { x, z };
  }

  get yaw() { return this._yaw; }
  get pitch() { return this._pitch; }
  get locked() { return this._locked; }

  lock() {
    if (!this._locked) {
      const canvasEl = document.querySelector('canvas');
      canvasEl.requestPointerLock();
    }
  }

  unlock() {
    if (this._locked) {
      document.exitPointerLock();
    }
  }

  get justPressed() { return this._justPressed; }

  reset() {
    this._keys = {};
    this._justPressed.clear();
    this._yaw = C.PLAYER.startYaw;
    this._pitch = 0;
  }
}

export { Input };

